        esquerda.setObjectName("myEvolutionPanel")
        esquerda.setMinimumWidth(280)
        esquerda.setMaximumWidth(380)
        el = QVBoxLayout(esquerda)
        el.setContentsMargins(12, 10, 12, 12)
        el.setSpacing(8)

        arvore_titulo = QLabel("Disciplinas e tópicos")
