    def alterar_inclusao_materia(
        self,
        disciplina_id
    ):
        linha = self.linhas_personalizadas[
            disciplina_id
        ]

        marcado = linha[
            "check"
        ].isChecked()

        spin = linha[
            "spin"
        ]

        spin.setEnabled(
            marcado
        )

        if marcado:
            if spin.value() <= 0:
                spin.setValue(
                    min(
                        5,
                        linha[
                            "dados"
                        ][
                            "disponiveis"
                        ]
                    )
                )
        else:
            spin.setValue(
                0
            )

        self.atualizar_resumo_personalizado()

    def quantidades_personalizadas(
        self
    ):
        resultado = {}

        for disciplina_id, linha in (
            self.linhas_personalizadas.items()
        ):
            if not linha[
                "check"
            ].isChecked():
                continue

            quantidade = linha[
                "spin"
            ].value()

            if quantidade > 0:
                resultado[
                    disciplina_id
                ] = quantidade

        return resultado

    def atualizar_resumo_personalizado(
        self
    ):
        quantidades = (
            self.quantidades_personalizadas()
        )

        total = sum(
            quantidades.values()
        )

        materias = len(
            quantidades
        )

        if total <= 0:
            self.personalizado_resumo.setText(
                "Nenhuma matéria selecionada."
            )
            if self.tipo.currentIndex() == 0:
                self.iniciar.setEnabled(
                    False
                )
            return

        self.personalizado_resumo.setText(
            (
                f"{total} questão(ões) • "
                f"{materias} matéria(s) selecionada(s)"
            )
        )

        if self.tipo.currentIndex() == 0:
            self.iniciar.setEnabled(
                True
            )

    def atualizar_preview_vighna(
        self
    ):
        if not self.disponibilidade:
            self.tabela_vighna.setRowCount(0)
            self.vighna_resumo.setText(
                "Nenhuma questão disponível no perfil ativo."
            )
            if self.tipo.currentIndex() in (1, 2):
                self.iniciar.setEnabled(False)
            return

        estrategia = (
            "estrategico"
            if self.tipo.currentIndex() == 2
            else "equilibrado"
        )
        plano = planejar_simulado_inteligente(
            self.concurso[0],
            self.quantidade_vighna.value(),
            estrategia=estrategia,
        )
        alocacoes = plano["alocacoes"]
        self.tabela_vighna.setRowCount(len(alocacoes))

        for linha, item in enumerate(alocacoes):
            if estrategia == "estrategico":
                criterio = (
                    f"{float(item.get('pressao_estrategica', 0.0)):.0f}/100"
                )
            else:
                criterio = f"{item['importancia_media']:.1f}/5"

            valores = [
                item["disciplina"],
                str(item["topicos"]),
                criterio,
                str(item["disponiveis"]),
                str(item["quantidade"]),
            ]
            for coluna, valor in enumerate(valores):
                celula = QTableWidgetItem(valor)
                if coluna > 0:
                    celula.setTextAlignment(Qt.AlignCenter)
                self.tabela_vighna.setItem(linha, coluna, celula)
            self.tabela_vighna.setRowHeight(linha, 32)

        if estrategia == "estrategico":
            self.tabela_vighna.setHorizontalHeaderItem(
                2, QTableWidgetItem("Pressão estratégica")
            )
            texto_modo = (
                "ajuste moderado por fragilidades • sem virar treino adaptativo"
            )
        else:
            self.tabela_vighna.setHorizontalHeaderItem(
                2, QTableWidgetItem("Importância média")
            )
            texto_modo = "distribuição estrutural • sem viés por desempenho"

        self.vighna_resumo.setText(
            f"{plano['quantidade']} questão(ões) • "
            f"{len(alocacoes)} matéria(s) • {texto_modo}"
        )
        if self.tipo.currentIndex() in (1, 2):
            self.iniciar.setEnabled(plano["quantidade"] > 0)

    def atualizar_tipo(
        self
    ):
        indice = self.tipo.currentIndex()
        self.paginas.setCurrentIndex(
            0 if indice == 0 else 1
        )

        if indice == 0:
            self.atualizar_resumo_personalizado()
        else:
            self.atualizar_preview_vighna()

    def confirmar(
        self
    ):
        preferir = self.preferir_ineditas.isChecked()
        tempo = self.tempo.value()
        indice_tipo = self.tipo.currentIndex()

        if indice_tipo == 0:
            quantidades = self.quantidades_personalizadas()
            if not quantidades:
                QMessageBox.information(
                    self,
                    "Prova real",
                    "Selecione ao menos uma matéria e defina uma quantidade de questões."
                )
                return
            selecao = montar_simulado_personalizado(
                self.concurso[0],
                quantidades,
                preferir_ineditas=preferir,
            )
            tipo = "Prova real"
            modo = "Simulado • Prova real"
            estrategia_simulado = "prova_real"
        else:
            estrategia_simulado = (
                "estrategico" if indice_tipo == 2 else "equilibrado"
            )
            selecao = montar_simulado_inteligente(
                self.concurso[0],
                self.quantidade_vighna.value(),
                estrategia=estrategia_simulado,
                preferir_ineditas=preferir,
            )
            if estrategia_simulado == "estrategico":
                tipo = "Estratégico"
                modo = "Simulado • Estratégico"
            else:
                tipo = "Equilibrado"
                modo = "Simulado • Equilibrado"

        fila = selecao["fila"]
        if not fila:
            QMessageBox.information(
                self,
                "Simulado",
                "Não foi possível montar o simulado."
            )
            return

        plano = selecao["plano"]
        indices = obter_indices_dominio_topicos(self.concurso[0])
        topicos_ids = {
            int(item["topico_id"])
            for item in fila
            if item.get("topico_id") is not None
        }
        dominio_antes = {
            str(topico_id): {
                "score": round(float(indices.get(topico_id, {}).get("score", 0.0) or 0.0), 1),
                "nivel": indices.get(topico_id, {}).get("nivel", "Sem evidência"),
            }
            for topico_id in topicos_ids
        }

        self.configuracao = {
            "concurso_id": self.concurso[0],
            "concurso_nome": self.concurso[1],
            "disciplina_id": None,
            "disciplina_nome": "Múltiplas matérias",
            "topico_id": None,
            "topico_nome": "Múltiplos tópicos",
            "modo": modo,
            "origem_sessao": "simulado",
            "quantidade": len(fila),
            "fila": fila,
            "modo_simulado": True,
            "tipo_simulado": tipo,
            "versao_simulado": "simulado_v2",
            "estrategia_simulado": estrategia_simulado,
            "feedback_imediato": False,
            "integrar_revisoes": False,
            "tempo_limite_minutos": tempo,
            "preferir_ineditas": preferir,
            "plano_simulado": plano,
            "dominio_antes_simulado": dominio_antes,
        }
        self.accept()


