    def configurar_tabela(
        self,
        tabela,
        coluna_stretch=0
    ):
        tabela.setEditTriggers(
            QAbstractItemView.NoEditTriggers
        )
        tabela.setSelectionBehavior(
            QAbstractItemView.SelectRows
        )
        tabela.setSelectionMode(
            QAbstractItemView.SingleSelection
        )
        tabela.setAlternatingRowColors(
            True
        )
        tabela.setShowGrid(
            False
        )
        tabela.verticalHeader().setVisible(
            False
        )
        tabela.setHorizontalScrollBarPolicy(
            Qt.ScrollBarAlwaysOff
        )

        header = tabela.horizontalHeader()

        for coluna in range(
            tabela.columnCount()
        ):
            header.setSectionResizeMode(
                coluna,
                (
                    QHeaderView.Stretch
                    if coluna == coluna_stretch
                    else QHeaderView.ResizeToContents
                )
            )

    def periodo_dias(
        self
    ):
        return {
            "30 dias": 30,
            "90 dias": 90,
            "180 dias": 180,
            "Todo período": None,
        }.get(
            self.periodo.currentText(),
            90
        )

    def formatar_percentual_local(
        self,
        valor
    ):
        if valor is None:
            return "—"

        return (
            f"{float(valor):.1f}%"
        )

    def formatar_delta(
        self,
        valor,
        sufixo=""
    ):
        if valor is None:
            return "—"

        valor = float(
            valor
        )

        sinal = (
            "+"
            if valor > 0
            else ""
        )

        return (
            f"{sinal}{valor:.1f}{sufixo}"
        )

    def formatar_tempo(
        self,
        segundos
    ):
        if segundos is None:
            return "—"

        segundos = float(
            segundos
        )

        if segundos < 60.0:
            return (
                f"{segundos:.0f} s/Q"
            )

        return (
            f"{segundos / 60.0:.1f} min/Q"
        )

    def formatar_data_hora(
        self,
        texto
    ):
        texto = str(
            texto
            or ""
        )

        try:
            momento = datetime.strptime(
                texto[
                    :19
                ],
                "%Y-%m-%d %H:%M:%S"
            )
            return momento.strftime(
                "%d/%m/%Y %H:%M"
            )
        except Exception:
            return texto or "—"

    def carregar(
        self
    ):
        somente_adaptativas = (
            self.tipo_sessoes.currentText()
            == "Treinos adaptativos"
        )

        dados = obter_central_efetividade(
            self.concurso[0],
            dias=self.periodo_dias(),
            somente_adaptativas=(
                somente_adaptativas
            )
        )

        resumo = dados[
            "resumo"
        ]

        self.stat_sessoes.setText(
            str(
                resumo[
                    "sessoes"
                ]
            )
        )
        self.stat_sessoes_hint.setText(
            (
                "sessões com linha de base "
                "antes/depois"
            )
        )

        self.stat_respostas.setText(
            str(
                resumo[
                    "respostas"
                ]
            )
        )
        self.stat_respostas_hint.setText(
            (
                f"{resumo['acertos']} acerto(s)"
            )
        )

        self.stat_desempenho.setText(
            self.formatar_percentual_local(
                resumo[
                    "desempenho"
                ]
            )
        )
        self.stat_desempenho_hint.setText(
            "nas respostas monitoradas"
        )

        self.stat_dominio.setText(
            self.formatar_delta(
                resumo[
                    "delta_dominio"
                ]
            )
        )
        self.stat_dominio_hint.setText(
            "média por tópico tocado"
        )

        self.stat_cobertura.setText(
            self.formatar_delta(
                resumo[
                    "delta_cobertura"
                ],
                " p.p."
            )
        )
        self.stat_cobertura_hint.setText(
            "média por tópico tocado"
        )

        self.stat_tempo.setText(
            self.formatar_tempo(
                resumo[
                    "tempo_medio_questao"
                ]
            )
        )
        self.stat_tempo_hint.setText(
            "tempo efetivo registrado"
        )

        calibracao = dados[
            "calibracao"
        ]

        self.calibracao_status.setText(
            (
                f"{calibracao['status']} • "
                f"confiança {calibracao['confianca'].lower()}"
            )
        )

        mapa_estado = {
            "Insuficiente": "insuficiente",
            "Inicial": "inicial",
            "Moderada": "moderada",
            "Forte": "forte",
        }

        self.calibracao_status.setProperty(
            "calibrationLevel",
            mapa_estado.get(
                calibracao[
                    "confianca"
                ],
                "insuficiente"
            )
        )
        self.calibracao_status.style().unpolish(
            self.calibracao_status
        )
        self.calibracao_status.style().polish(
            self.calibracao_status
        )

        self.calibracao_texto.setText(
            (
                f"{calibracao['sessoes_adaptativas']} treino(s) adaptativo(s) "
                f"e {calibracao['respostas_adaptativas']} resposta(s) na base. "
                f"{calibracao['orientacao']}"
            )
        )

        pesos = calibracao[
            "pesos_atuais"
        ]

        pesos_texto = " • ".join(
            f"{nome.lower()} {valor}%"
            for nome, valor in pesos.items()
        )

        self.calibracao_pesos.setText(
            (
                "Seleção Adaptativa V2 — pesos atuais: "
                + pesos_texto
                + ". A calibração continua observacional; os pesos não são "
                "alterados automaticamente sem uma etapa futura específica."
            )
        )

        self.calibracao_observacoes.setText(
            "\n".join(
                (
                    f"• {texto}"
                    for texto in calibracao[
                        "observacoes"
                    ]
                )
            )
        )

        # ----------------------------------------------------
        # MOTIVOS
        # ----------------------------------------------------

        motivos = dados[
            "motivos"
        ]

        self.tabela_motivos.setRowCount(
            len(
                motivos
            )
        )

        for linha, item in enumerate(
            motivos
        ):
            valores = [
                item[
                    "motivo"
                ],
                str(
                    item[
                        "sessoes"
                    ]
                ),
                str(
                    item[
                        "respostas"
                    ]
                ),
                self.formatar_percentual_local(
                    item[
                        "desempenho"
                    ]
                ),
                self.formatar_delta(
                    item[
                        "delta_dominio"
                    ]
                ),
                self.formatar_delta(
                    item[
                        "delta_cobertura"
                    ],
                    " p.p."
                ),
                (
                    f"{item['delta_recorrentes']:+d}"
                    if item[
                        "delta_recorrentes"
                    ] != 0
                    else "0"
                ),
            ]

            for coluna, valor in enumerate(
                valores
            ):
                celula = QTableWidgetItem(
                    valor
                )

                if coluna > 0:
                    celula.setTextAlignment(
                        Qt.AlignCenter
                    )

                if coluna == 0:
                    celula.setToolTip(
                        (
                            "Motivo predominante usado para escolher "
                            "o tópico naquela sessão."
                        )
                    )

                self.tabela_motivos.setItem(
                    linha,
                    coluna,
                    celula
                )

            self.tabela_motivos.setRowHeight(
                linha,
                30
            )

        # ----------------------------------------------------
        # SESSÕES
        # ----------------------------------------------------

        sessoes = dados[
            "sessoes"
        ]

        self.tabela_sessoes.setRowCount(
            len(
                sessoes
            )
        )

        for linha, item in enumerate(
            sessoes
        ):
            dominio_texto = (
                "—"
                if item[
                    "dominio_antes"
                ] is None
                else (
                    f"{item['dominio_antes']:.1f} → "
                    f"{item['dominio_depois']:.1f} "
                    f"({self.formatar_delta(item['delta_dominio'])})"
                )
            )

            cobertura_texto = (
                "—"
                if item[
                    "cobertura_antes"
                ] is None
                else (
                    f"{item['cobertura_antes']:.1f}% → "
                    f"{item['cobertura_depois']:.1f}% "
                    f"({self.formatar_delta(item['delta_cobertura'], ' p.p.')})"
                )
            )

            recorrentes_texto = (
                f"{item['recorrentes_antes']} → "
                f"{item['recorrentes_depois']}"
            )

            valores = [
                self.formatar_data_hora(
                    item[
                        "criado_em"
                    ]
                ),
                item[
                    "modo"
                ],
                item[
                    "escopo"
                ],
                str(
                    item[
                        "respostas"
                    ]
                ),
                self.formatar_percentual_local(
                    item[
                        "desempenho"
                    ]
                ),
                dominio_texto,
                cobertura_texto,
                recorrentes_texto,
            ]

            for coluna, valor in enumerate(
                valores
            ):
                celula = QTableWidgetItem(
                    valor
                )

                if coluna in (
                    3,
                    4,
                    5,
                    6,
                    7,
                ):
                    celula.setTextAlignment(
                        Qt.AlignCenter
                    )

                self.tabela_sessoes.setItem(
                    linha,
                    coluna,
                    celula
                )

            self.tabela_sessoes.setRowHeight(
                linha,
                30
            )


