    def carregar(self):
        dados = listar_conteudos_concurso(
            self.concurso_id
        )

        self.atualizando_arvore = True
        self.arvore.clear()

        for disciplina in dados:
            item_disciplina = QTreeWidgetItem(
                self.arvore
            )

            item_disciplina.setText(
                0,
                disciplina[
                    "disciplina"
                ]
            )

            item_disciplina.setData(
                0,
                Qt.UserRole,
                (
                    "disciplina",
                    disciplina[
                        "disciplina_id"
                    ]
                )
            )

            item_disciplina.setFlags(
                item_disciplina.flags()
                | Qt.ItemIsUserCheckable
            )

            item_disciplina.setCheckState(
                0,
                (
                    Qt.Checked
                    if disciplina[
                        "incluida"
                    ]
                    else Qt.Unchecked
                )
            )

            item_disciplina.setText(
                1,
                "—"
            )

            for topico in disciplina[
                "topicos"
            ]:
                item_topico = QTreeWidgetItem(
                    item_disciplina
                )

                item_topico.setText(
                    0,
                    topico[
                        "topico"
                    ]
                )

                item_topico.setData(
                    0,
                    Qt.UserRole,
                    (
                        "topico",
                        topico[
                            "topico_id"
                        ]
                    )
                )

                item_topico.setFlags(
                    item_topico.flags()
                    | Qt.ItemIsUserCheckable
                )

                item_topico.setCheckState(
                    0,
                    (
                        Qt.Checked
                        if topico[
                            "incluido"
                        ]
                        else Qt.Unchecked
                    )
                )

                importancia = int(
                    topico[
                        "importancia"
                    ]
                )

                item_topico.setData(
                    1,
                    Qt.UserRole,
                    importancia
                )

                item_topico.setText(
                    1,
                    f"{importancia}/5"
                )

                for capitulo in listar_capitulos_topico(
                    topico[
                        "topico_id"
                    ]
                ):
                    item_capitulo = QTreeWidgetItem(
                        item_topico
                    )

                    item_capitulo.setText(
                        0,
                        f"Capítulo: {capitulo[1]}"
                    )
                    item_capitulo.setData(
                        0,
                        Qt.UserRole,
                        (
                            "capitulo",
                            capitulo[0]
                        )
                    )
                    item_capitulo.setText(
                        1,
                        ""
                    )

        self.atualizando_arvore = False
        self.arvore.expandToDepth(
            0
        )
        self.filtrar_conteudos(
            self.busca_conteudos.text()
        )

    @staticmethod
    def normalizar_busca(texto):
        texto = unicodedata.normalize(
            "NFD",
            str(texto or "")
        )
        return "".join(
            caractere
            for caractere in texto
            if unicodedata.category(caractere) != "Mn"
        ).casefold()

    def filtrar_conteudos(
        self,
        texto
    ):
        termo = self.normalizar_busca(
            texto
        )
        possui_filtro = bool(
            termo
        )

        self.atualizando_arvore = True

        try:
            for indice in range(
                self.arvore.topLevelItemCount()
            ):
                disciplina = self.arvore.topLevelItem(
                    indice
                )
                disciplina_corresponde = (
                    termo in self.normalizar_busca(
                        disciplina.text(0)
                    )
                )
                possui_resultado = disciplina_corresponde

                for indice_topico in range(
                    disciplina.childCount()
                ):
                    topico = disciplina.child(
                        indice_topico
                    )
                    topico_corresponde = (
                        termo in self.normalizar_busca(
                            topico.text(0)
                        )
                    )
                    capitulo_corresponde = False

                    for indice_capitulo in range(
                        topico.childCount()
                    ):
                        capitulo = topico.child(
                            indice_capitulo
                        )
                        encontrado = (
                            termo in self.normalizar_busca(
                                capitulo.text(0)
                            )
                        )
                        capitulo_corresponde = (
                            capitulo_corresponde
                            or encontrado
                        )
                        capitulo.setHidden(
                            possui_filtro
                            and not (
                                disciplina_corresponde
                                or topico_corresponde
                                or encontrado
                            )
                        )

                    exibir_topico = (
                        not possui_filtro
                        or disciplina_corresponde
                        or topico_corresponde
                        or capitulo_corresponde
                    )
                    topico.setHidden(
                        not exibir_topico
                    )
                    possui_resultado = (
                        possui_resultado
                        or exibir_topico
                    )

                    if (
                        possui_filtro
                        and (
                            topico_corresponde
                            or capitulo_corresponde
                        )
                    ):
                        topico.setExpanded(
                            True
                        )

                disciplina.setHidden(
                    possui_filtro
                    and not possui_resultado
                )

                if possui_filtro and possui_resultado:
                    disciplina.setExpanded(
                        True
                    )

        finally:
            self.atualizando_arvore = False

    def item_alterado(
        self,
        item,
        coluna
    ):
        if (
            self.atualizando_arvore
            or coluna != 0
        ):
            return

        dados = item.data(
            0,
            Qt.UserRole
        )

        if not dados:
            return

        tipo = dados[0]

        self.atualizando_arvore = True

        try:
            if tipo == "disciplina":
                estado = item.checkState(
                    0
                )

                # Facilita o uso:
                # marcar a matéria inclui todos os seus tópicos;
                # desmarcar retira todos.
                for indice in range(
                    item.childCount()
                ):
                    item.child(
                        indice
                    ).setCheckState(
                        0,
                        estado
                    )

            elif tipo == "topico":
                # Se um tópico for marcado manualmente,
                # garante que a matéria também fique incluída.
                if (
                    item.checkState(0)
                    == Qt.Checked
                    and item.parent() is not None
                    and item.parent().checkState(0)
                    != Qt.Checked
                ):
                    item.parent().setCheckState(
                        0,
                        Qt.Checked
                    )

        finally:
            self.atualizando_arvore = False

    def editar_importancia(
        self,
        item,
        coluna
    ):
        dados = item.data(
            0,
            Qt.UserRole
        )

        if (
            not dados
            or dados[0] != "topico"
        ):
            return

        atual = item.data(
            1,
            Qt.UserRole
        )

        atual = int(
            atual or 3
        )

        opcoes = [
            "1 — Baixa",
            "2 — Menor",
            "3 — Normal",
            "4 — Alta",
            "5 — Muito alta"
        ]

        escolha, confirmou = QInputDialog.getItem(
            self,
            "Importância no concurso",
            (
                f"{item.text(0)}\n\n"
                f"Perfil: {self.concurso_nome}"
            ),
            opcoes,
            atual - 1,
            False
        )

        if not confirmou:
            return

        importancia = int(
            escolha.split(
                "—"
            )[0].strip()
        )

        item.setData(
            1,
            Qt.UserRole,
            importancia
        )

        item.setText(
            1,
            f"{importancia}/5"
        )

    def definir_todos(
        self,
        estado
    ):
        self.atualizando_arvore = True

        try:
            for indice in range(
                self.arvore.topLevelItemCount()
            ):
                disciplina = (
                    self.arvore.topLevelItem(
                        indice
                    )
                )

                disciplina.setCheckState(
                    0,
                    estado
                )

                for filho in range(
                    disciplina.childCount()
                ):
                    disciplina.child(
                        filho
                    ).setCheckState(
                        0,
                        estado
                    )

        finally:
            self.atualizando_arvore = False

    def salvar(self):
        disciplinas = []
        topicos = []

        for indice in range(
            self.arvore.topLevelItemCount()
        ):
            disciplina = (
                self.arvore.topLevelItem(
                    indice
                )
            )

            dados_disciplina = (
                disciplina.data(
                    0,
                    Qt.UserRole
                )
            )

            disciplina_id = (
                dados_disciplina[1]
            )

            incluida = (
                disciplina.checkState(0)
                == Qt.Checked
            )

            disciplinas.append(
                (
                    disciplina_id,
                    incluida
                )
            )

            for filho in range(
                disciplina.childCount()
            ):
                topico = disciplina.child(
                    filho
                )

                dados_topico = topico.data(
                    0,
                    Qt.UserRole
                )

                topico_id = (
                    dados_topico[1]
                )

                incluido = (
                    topico.checkState(0)
                    == Qt.Checked
                )

                importancia = int(
                    topico.data(
                        1,
                        Qt.UserRole
                    )
                    or 3
                )

                topicos.append(
                    (
                        topico_id,
                        incluido,
                        importancia
                    )
                )

        if salvar_conteudos_concurso(
            self.concurso_id,
            disciplinas,
            topicos
        ):
            self.accept()
        else:
            QMessageBox.critical(
                self,
                "Falha ao salvar",
                "Não foi possível salvar as associações deste perfil."
            )


