            titulo_label.setObjectName(
                "weeklyGoalMetricTitle"
            )

            valor_label = QLabel(
                "—"
            )
            valor_label.setObjectName(
                "weeklyGoalValue"
            )

            barra = QProgressBar()
            barra.setObjectName(
                "weeklyGoalProgress"
            )
            barra.setRange(
                0,
                100
            )
            barra.setValue(
                0
            )
            barra.setTextVisible(
                False
            )
            barra.setFixedHeight(
                6
            )

            dica = QLabel(
                "Meta desativada"
            )
            dica.setObjectName(
                "weeklyGoalHint"
            )

            card_layout.addWidget(
                titulo_label
            )
            card_layout.addWidget(
                valor_label
            )
            card_layout.addWidget(
                barra
            )
            card_layout.addWidget(
                dica
            )

            self.metas_semanais_widgets[
                chave
            ] = {
                "card": card,
                "valor": valor_label,
                "barra": barra,
                "dica": dica,
            }

            return card

