    def definir_tendencia_resumo(
        self,
        label,
        atual,
        media,
        maior_melhor=True,
        sufixo=""
    ):
        if media is None:
            label.setText(
                "• Sem histórico suficiente"
            )
            estado = "neutra"

        else:
            diferenca = (
                atual
                - media
            )

            tolerancia = (
                0.05
                if abs(media) < 1
                else max(
                    0.5,
                    abs(media) * 0.03
                )
            )

            if abs(diferenca) <= tolerancia:
                label.setText(
                    "• Próximo da média"
                )
                estado = "neutra"
            else:
                melhorou = (
                    diferenca > 0
                    if maior_melhor
                    else diferenca < 0
                )

                seta = (
                    "▲"
                    if diferenca > 0
                    else "▼"
                )

                label.setText(
                    f"{seta} {abs(diferenca):.1f}{sufixo} vs. média"
                )

                estado = (
                    "positiva"
                    if melhorou
                    else "negativa"
                )

        label.setProperty(
            "trendState",
            estado
        )

        label.style().unpolish(
            label
        )
        label.style().polish(
            label
        )

    def atualizar_resumo_dia(self):
        hoje_qdate = QDate.currentDate()
        hoje = hoje_qdate.toString(
            "yyyy-MM-dd"
        )

        concurso = obter_concurso_ativo()
        concurso_id = concurso[0]

        self.perfil_resumo_dia.setText(
            f"Perfil: {concurso[1]}"
        )

        self.resumo_dia_subtitulo.setText(
            f"Fechamento dos estudos de {hoje_qdate.toString('dd/MM/yyyy')}."
        )

        # ----------------------------------------------------
        # HOJE
        # ----------------------------------------------------

        dados_hoje = obter_relatorio_periodo(
            hoje,
            hoje,
            concurso_id
        )

        revisoes = int(
            dados_hoje.get(
                "revisoes",
                0
            )
            or 0
        )
        questoes = int(
            dados_hoje.get(
                "questoes",
                0
            )
            or 0
        )
        acertos = int(
            dados_hoje.get(
                "acertos",
                0
            )
            or 0
        )
        desempenho = dados_hoje.get(
            "percentual"
        )

        pendencias = listar_pendencias(
            hoje,
            concurso_id
        )

        meta = max(
            0,
            obter_configuracao_int(
                "meta_questoes_diaria",
                60
            )
        )

        self.resumo_card_revisoes.setText(
            str(
                revisoes
            )
        )
        self.resumo_card_questoes.setText(
            str(
                questoes
            )
        )
        self.resumo_card_acertos.setText(
            str(
                acertos
            )
        )
        self.resumo_card_desempenho.setText(
            formatar_percentual(
                desempenho
            )
        )
        self.resumo_card_pendencias.setText(
            str(
                len(
                    pendencias
                )
            )
        )

        if meta > 0:
            self.resumo_card_meta.setText(
                f"{questoes}/{meta}"
            )

            percentual_meta = round(
                100.0
                * questoes
                / meta
            )

            self.resumo_meta_barra.setValue(
                min(
                    100,
                    max(
                        0,
                        int(
                            percentual_meta
                        )
                    )
                )
            )

            self.resumo_meta_texto.setText(
                f"{questoes} / {meta} questões"
            )

            if questoes >= meta:
                excedente = (
                    questoes
                    - meta
                )

                if excedente > 0:
                    texto_meta = (
                        f"Meta concluída • +{excedente} questões acima da meta."
                    )
                else:
                    texto_meta = (
                        "Meta diária concluída."
                    )

                estado_meta = "concluida"

            else:
                faltam = (
                    meta
                    - questoes
                )

                texto_meta = (
                    f"{percentual_meta}% da meta • faltam {faltam} questões."
                )
                estado_meta = "andamento"

        else:
            self.resumo_card_meta.setText(
                "Desativada"
            )
            self.resumo_meta_barra.setValue(
                0
            )
            self.resumo_meta_texto.setText(
                f"{questoes} questões hoje"
            )
            texto_meta = (
                "A meta diária está desativada."
            )
            estado_meta = "desativada"

        self.resumo_meta_status.setText(
            texto_meta
        )
        self.resumo_meta_status.setProperty(
            "goalState",
            estado_meta
        )
        self.resumo_meta_barra.setProperty(
            "goalState",
            estado_meta
        )

        for widget in (
            self.resumo_meta_status,
            self.resumo_meta_barra
        ):
            widget.style().unpolish(
                widget
            )
            widget.style().polish(
                widget
            )

        # ----------------------------------------------------
        # MÉDIA DOS 7 DIAS ANTERIORES
        # ----------------------------------------------------

        inicio_anterior_qdate = (
            hoje_qdate.addDays(
                -7
            )
        )
        fim_anterior_qdate = (
            hoje_qdate.addDays(
                -1
            )
        )

        inicio_anterior = (
            inicio_anterior_qdate.toString(
                "yyyy-MM-dd"
            )
        )
        fim_anterior = (
            fim_anterior_qdate.toString(
                "yyyy-MM-dd"
            )
        )

        dados_anteriores = obter_relatorio_periodo(
            inicio_anterior,
            fim_anterior,
            concurso_id
        )

        media_questoes = (
            float(
                dados_anteriores.get(
                    "questoes",
                    0
                )
                or 0
            )
            / 7.0
        )

        media_revisoes = (
            float(
                dados_anteriores.get(
                    "revisoes",
                    0
                )
                or 0
            )
            / 7.0
        )

        desempenho_anterior = (
            dados_anteriores.get(
                "percentual"
            )
        )

        self.resumo_periodo_comparacao.setText(
            (
                f"{inicio_anterior_qdate.toString('dd/MM')} "
                f"a {fim_anterior_qdate.toString('dd/MM')}"
            )
        )

        self.resumo_comp_questoes_hoje.setText(
            f"Hoje: {questoes}"
        )
        self.resumo_comp_questoes_media.setText(
            f"Média: {media_questoes:.1f}/dia"
        )

        self.resumo_comp_revisoes_hoje.setText(
            f"Hoje: {revisoes}"
        )
        self.resumo_comp_revisoes_media.setText(
            f"Média: {media_revisoes:.1f}/dia"
        )

        self.resumo_comp_desempenho_hoje.setText(
            (
                f"Hoje: {formatar_percentual(desempenho)}"
            )
        )
        self.resumo_comp_desempenho_media.setText(
            (
                "Média: "
                + formatar_percentual(
                    desempenho_anterior
                )
            )
        )

        self.definir_tendencia_resumo(
            self.resumo_comp_questoes_tendencia,
            float(
                questoes
            ),
            media_questoes,
            True,
            ""
        )

        self.definir_tendencia_resumo(
            self.resumo_comp_revisoes_tendencia,
            float(
                revisoes
            ),
            media_revisoes,
            True,
            ""
        )

        if desempenho is None:
            self.resumo_comp_desempenho_tendencia.setText(
                "• Sem resultado hoje"
            )
            self.resumo_comp_desempenho_tendencia.setProperty(
                "trendState",
                "neutra"
            )
            self.resumo_comp_desempenho_tendencia.style().unpolish(
                self.resumo_comp_desempenho_tendencia
            )
            self.resumo_comp_desempenho_tendencia.style().polish(
                self.resumo_comp_desempenho_tendencia
            )
        elif desempenho_anterior is None:
            self.resumo_comp_desempenho_tendencia.setText(
                "• Sem histórico suficiente"
            )
            self.resumo_comp_desempenho_tendencia.setProperty(
                "trendState",
                "neutra"
            )
            self.resumo_comp_desempenho_tendencia.style().unpolish(
                self.resumo_comp_desempenho_tendencia
            )
            self.resumo_comp_desempenho_tendencia.style().polish(
                self.resumo_comp_desempenho_tendencia
            )
        else:
            self.definir_tendencia_resumo(
                self.resumo_comp_desempenho_tendencia,
                float(
                    desempenho
                ),
                float(
                    desempenho_anterior
                ),
                True,
                " p.p."
            )

        # ----------------------------------------------------
        # TÓPICOS REVISADOS HOJE
        # ----------------------------------------------------

        topicos = obter_relatorio_topicos_periodo(
            hoje,
            hoje,
            concurso_id
        )

        quantidade_topicos = len(
            topicos
        )

        if quantidade_topicos == 1:
            self.resumo_topicos_contagem.setText(
                "• 1 tópico"
            )
        else:
            self.resumo_topicos_contagem.setText(
                f"• {quantidade_topicos} tópicos"
            )

        self.tabela_resumo_dia.setRowCount(
            quantidade_topicos
        )

        for linha, dado in enumerate(
            topicos
        ):
            topico_id = dado[0]
            disciplina = dado[1]
            topico = dado[2]
            numero_revisoes = dado[3]
            qtd_questoes = dado[4]
            qtd_acertos = dado[5]
            percentual = dado[6]

            item_disciplina = QTableWidgetItem(
                disciplina
            )

            item_topico = QTableWidgetItem(
                topico
            )
            item_topico.setData(
                Qt.UserRole,
                topico_id
            )

            item_revisoes = QTableWidgetItem(
                str(
                    numero_revisoes
                )
            )
            item_revisoes.setTextAlignment(
                Qt.AlignCenter
            )

            item_questoes = QTableWidgetItem(
                str(
                    qtd_questoes
                )
            )
            item_questoes.setTextAlignment(
                Qt.AlignCenter
            )

            item_acertos = QTableWidgetItem(
                str(
                    qtd_acertos
                )
            )
            item_acertos.setTextAlignment(
                Qt.AlignCenter
            )

            item_percentual = QTableWidgetItem(
                formatar_percentual(
                    percentual
                )
            )
            item_percentual.setTextAlignment(
                Qt.AlignCenter
            )

            if percentual is not None:
                if percentual < 60:
                    aplicar_destaque_tabela(
                        item_percentual,
                        "perigo",
                        True
                    )
                elif percentual < 70:
                    aplicar_destaque_tabela(
                        item_percentual,
                        "alerta",
                        True
                    )
                elif percentual < 80:
                    aplicar_destaque_tabela(
                        item_percentual,
                        "atencao",
                        True
                    )
                elif percentual >= 90:
                    aplicar_destaque_tabela(
                        item_percentual,
                        "sucesso",
                        False
                    )

            self.tabela_resumo_dia.setItem(
                linha,
                0,
                item_disciplina
            )
            self.tabela_resumo_dia.setItem(
                linha,
                1,
                item_topico
            )
            self.tabela_resumo_dia.setItem(
                linha,
                2,
                item_revisoes
            )
            self.tabela_resumo_dia.setItem(
                linha,
                3,
                item_questoes
            )
            self.tabela_resumo_dia.setItem(
                linha,
                4,
                item_acertos
            )
            self.tabela_resumo_dia.setItem(
                linha,
                5,
                item_percentual
            )

            self.tabela_resumo_dia.setRowHeight(
                linha,
                32
            )

    def abrir_topico_resumo_dia(
        self,
        linha,
        coluna
    ):
        item = self.tabela_resumo_dia.item(
            linha,
            1
        )

        if item is None:
            return

        janela = JanelaTopico(
            item.data(
                Qt.UserRole
            ),
            item.text(),
            self
        )

        janela.exec()

        self.atualizar_dashboard()
        self.atualizar_resumo_dia()

