    def abrir_calendario(self):
        self.atualizar_calendario()

        self.telas.setCurrentWidget(
            self.tela_calendario
        )

    def ir_para_hoje_calendario(self):
        hoje = QDate.currentDate()

        self.calendario_revisoes.setSelectedDate(
            hoje
        )
        self.calendario_revisoes.showSelectedDate()

        self.atualizar_calendario()

    def mudar_mes_calendario(
        self,
        ano,
        mes
    ):
        selecionada = (
            self.calendario_revisoes
            .selectedDate()
        )

        if (
            selecionada.year() != ano
            or selecionada.month() != mes
        ):
            hoje = QDate.currentDate()

            if (
                hoje.year() == ano
                and hoje.month() == mes
            ):
                nova_data = hoje
            else:
                nova_data = QDate(
                    ano,
                    mes,
                    1
                )

            self.calendario_revisoes.setSelectedDate(
                nova_data
            )

        self.atualizar_calendario_mes(
            ano,
            mes
        )
        self.atualizar_calendario_dia()

    def atualizar_calendario(self):
        concurso = obter_concurso_ativo()

        self.perfil_calendario.setText(
            f"Perfil: {concurso[1]}"
        )

        resumo = obter_dashboard(
            QDate.currentDate().toString(
                "yyyy-MM-dd"
            ),
            concurso[0]
        )

        self.calendario_card_hoje.setText(
            str(
                resumo["hoje"]
            )
        )
        self.calendario_card_atrasadas.setText(
            str(
                resumo["atrasadas"]
            )
        )

        ano = (
            self.calendario_revisoes
            .yearShown()
        )
        mes = (
            self.calendario_revisoes
            .monthShown()
        )

        self.atualizar_calendario_mes(
            ano,
            mes
        )
        self.atualizar_calendario_dia()

    def atualizar_calendario_mes(
        self,
        ano,
        mes
    ):
        inicio = QDate(
            ano,
            mes,
            1
        )
        fim = QDate(
            ano,
            mes,
            inicio.daysInMonth()
        )

        concurso_id = (
            obter_concurso_ativo()[0]
        )

        dados = listar_revisoes_agendadas_periodo(
            inicio.toString(
                "yyyy-MM-dd"
            ),
            fim.toString(
                "yyyy-MM-dd"
            ),
            concurso_id
        )

        self.dados_calendario_mes = list(
            dados
        )

        self.calendario_card_mes.setText(
            str(
                len(
                    self.dados_calendario_mes
                )
            )
        )

        dias_ocupados = {
            item[4]
            for item in self.dados_calendario_mes
        }

        self.calendario_card_dias.setText(
            str(
                len(
                    dias_ocupados
                )
            )
        )

        # Limpa somente as datas formatadas anteriormente.
        for data_antiga in getattr(
            self,
            "datas_formatadas_calendario",
            set()
        ):
            self.calendario_revisoes.setDateTextFormat(
                data_antiga,
                QTextCharFormat()
            )

        self.datas_formatadas_calendario = set()

        hoje = QDate.currentDate()

        tema_atual = normalizar_tema(
            obter_configuracao_texto(
                "tema_interface",
                "claro"
            )
        )

        if tema_atual == "futurista":
            cores = {
                "hoje": (
                    "#BDF7FF",
                    "#124E68"
                ),
                "atrasada": (
                    "#FF9BAC",
                    "#4B1D2C"
                ),
                "agendada": (
                    "#74F1C5",
                    "#124334"
                )
            }
        elif tema_atual == "escuro":
            cores = {
                "hoje": (
                    "#93c5fd",
                    "#1e3a8a"
                ),
                "atrasada": (
                    "#fca5a5",
                    "#4c1d24"
                ),
                "agendada": (
                    "#86efac",
                    "#163523"
                )
            }
        else:
            cores = {
                "hoje": (
                    "#1d4ed8",
                    "#dbeafe"
                ),
                "atrasada": (
                    "#b91c1c",
                    "#fee2e2"
                ),
                "agendada": (
                    "#15803d",
                    "#dcfce7"
                )
            }

        for data_texto in sorted(
            dias_ocupados
        ):
            data = QDate.fromString(
                data_texto,
                "yyyy-MM-dd"
            )

            if not data.isValid():
                continue

            if data < hoje:
                chave = "atrasada"
            elif data == hoje:
                chave = "hoje"
            else:
                chave = "agendada"

            formato = QTextCharFormat()
            formato.setForeground(
                QColor(
                    cores[chave][0]
                )
            )
            formato.setBackground(
                QColor(
                    cores[chave][1]
                )
            )
            formato.setFontWeight(
                int(
                    QFont.Weight.Bold
                )
            )

            self.calendario_revisoes.setDateTextFormat(
                data,
                formato
            )

            self.datas_formatadas_calendario.add(
                data
            )

    def atualizar_calendario_dia(self):
        if not hasattr(
            self,
            "tabela_calendario"
        ):
            return

        data = (
            self.calendario_revisoes
            .selectedDate()
        )

        data_texto = data.toString(
            "yyyy-MM-dd"
        )

        self.calendario_data_titulo.setText(
            f"Revisões de {data.toString('dd/MM/yyyy')}"
        )

        dados_dia = [
            item
            for item in getattr(
                self,
                "dados_calendario_mes",
                []
            )
            if item[4] == data_texto
        ]

        quantidade = len(
            dados_dia
        )

        texto_quantidade = (
            "1 revisão"
            if quantidade == 1
            else f"{quantidade} revisões"
        )

        self.calendario_contagem_dia.setText(
            texto_quantidade
        )

        self.tabela_calendario.setRowCount(
            quantidade
        )

        hoje = QDate.currentDate()

        for linha, dado in enumerate(
            dados_dia
        ):
            topico_id = dado[0]
            disciplina = dado[1]
            topico = dado[2]
            revisoes = dado[3]
            percentual = dado[5]
            importancia = dado[6]

            item_disciplina = QTableWidgetItem(
                disciplina
            )

            item_topico = QTableWidgetItem(
                topico
            )
            item_topico.setData(
                Qt.UserRole,
                topico_id
            )

            item_revisoes = QTableWidgetItem(
                str(
                    revisoes
                )
            )
            item_revisoes.setTextAlignment(
                Qt.AlignCenter
            )

            item_percentual = QTableWidgetItem(
                formatar_percentual(
                    percentual
                )
            )
            item_percentual.setTextAlignment(
                Qt.AlignCenter
            )

            if data < hoje:
                situacao = "Atrasada"
                nivel = "perigo"
            elif data == hoje:
                situacao = "Hoje"
                nivel = "atencao"
            else:
                situacao = "Agendada"
                nivel = "sucesso"

            item_situacao = QTableWidgetItem(
                situacao
            )
            item_situacao.setTextAlignment(
                Qt.AlignCenter
            )
            aplicar_destaque_tabela(
                item_situacao,
                nivel,
                False
            )

            self.tabela_calendario.setItem(
                linha,
                0,
                item_disciplina
            )
            self.tabela_calendario.setItem(
                linha,
                1,
                item_topico
            )
            self.tabela_calendario.setItem(
                linha,
                2,
                item_revisoes
            )
            self.tabela_calendario.setItem(
                linha,
                3,
                item_percentual
            )

            estrelas = IndicadorEstrelasFila(
                importancia
            )

            self.tabela_calendario.setCellWidget(
                linha,
                4,
                estrelas
            )

            self.tabela_calendario.setItem(
                linha,
                5,
                item_situacao
            )

            self.tabela_calendario.setRowHeight(
                linha,
                32
            )

        if quantidade:
            self.tabela_calendario.selectRow(
                0
            )

    def obter_topico_calendario_selecionado(
        self
    ):
        linha = (
            self.tabela_calendario
            .currentRow()
        )

        if linha < 0:
            return (
                None,
                None
            )

        item = self.tabela_calendario.item(
            linha,
            1
        )

        if item is None:
            return (
                None,
                None
            )

        return (
            item.data(
                Qt.UserRole
            ),
            item.text()
        )

    def abrir_topico_calendario(
        self,
        linha,
        coluna
    ):
        item = self.tabela_calendario.item(
            linha,
            1
        )

        if item is None:
            return

        topico_id = item.data(
            Qt.UserRole
        )
        nome_topico = item.text()

        janela = JanelaTopico(
            topico_id,
            nome_topico,
            self
        )

        janela.exec()

        self.atualizar_dashboard()
        self.atualizar_calendario()

    def abrir_topico_calendario_selecionado(
        self
    ):
        topico_id, nome_topico = (
            self.obter_topico_calendario_selecionado()
        )

        if topico_id is None:
            QMessageBox.information(
                self,
                "Selecione uma revisão",
                "Selecione uma revisão da lista do dia."
            )
            return

        janela = JanelaTopico(
            topico_id,
            nome_topico,
            self
        )

        janela.exec()

        self.atualizar_dashboard()
        self.atualizar_calendario()

    def resolver_topico_calendario(self):
        topico_id, nome_topico = (
            self.obter_topico_calendario_selecionado()
        )

        if topico_id is None:
            QMessageBox.information(
                self,
                "Selecione uma revisão",
                "Selecione uma revisão da lista do dia."
            )
            return

        resultado = abrir_resolvedor_topico(
            topico_id,
            nome_topico,
            self
        )

        if resultado is not None:
            self.atualizar_dashboard()
            self.atualizar_calendario()

    def revisar_topico_calendario(self):
        topico_id, nome_topico = (
            self.obter_topico_calendario_selecionado()
        )

        if topico_id is None:
            QMessageBox.information(
                self,
                "Selecione uma revisão",
                "Selecione uma revisão da lista do dia."
            )
            return

        janela = JanelaRevisao(
            topico_id,
            nome_topico,
            self
        )

        if janela.exec() == QDialog.Accepted:
            self.atualizar_dashboard()
            self.atualizar_calendario()

