    def alterar_periodo_relatorio(self):
        hoje = QDate.currentDate()
        escolha = (
            self.combo_periodo_relatorio.currentText()
        )

        if escolha == "Últimos 7 dias":
            inicio = hoje.addDays(
                -6
            )
            fim = hoje
            personalizado = False

        elif escolha == "Últimos 30 dias":
            inicio = hoje.addDays(
                -29
            )
            fim = hoje
            personalizado = False

        elif escolha == "Este mês":
            inicio = QDate(
                hoje.year(),
                hoje.month(),
                1
            )
            fim = hoje
            personalizado = False

        else:
            personalizado = True

            if not self.data_inicio_relatorio.date().isValid():
                inicio = hoje.addDays(
                    -29
                )
            else:
                inicio = (
                    self.data_inicio_relatorio.date()
                )

            if not self.data_fim_relatorio.date().isValid():
                fim = hoje
            else:
                fim = (
                    self.data_fim_relatorio.date()
                )

        if not personalizado:
            self.data_inicio_relatorio.setDate(
                inicio
            )
            self.data_fim_relatorio.setDate(
                fim
            )

        self.data_inicio_relatorio.setEnabled(
            personalizado
        )
        self.data_fim_relatorio.setEnabled(
            personalizado
        )

    def abrir_relatorios(self):
        self.alterar_periodo_relatorio()
        self.atualizar_relatorios()

        self.telas.setCurrentWidget(
            self.tela_relatorios
        )

    def _comparar_numero(
        self,
        atual,
        anterior
    ):
        atual = float(
            atual or 0
        )
        anterior = float(
            anterior or 0
        )

        if anterior == 0:
            if atual == 0:
                return "0%"
            return "novo"

        variacao = (
            (atual - anterior)
            / anterior
            * 100.0
        )

        sinal = (
            "+"
            if variacao > 0
            else ""
        )

        return (
            f"{sinal}{variacao:.1f}%"
            .replace(
                ".",
                ","
            )
        )

    def atualizar_indicador_comparacao(
        self,
        label,
        texto,
        tendencia="neutral"
    ):
        label.setText(
            texto
        )

        label.setProperty(
            "reportTrend",
            tendencia
        )

        label.style().unpolish(
            label
        )
        label.style().polish(
            label
        )

    def atualizar_relatorios(self):
        inicio_q = (
            self.data_inicio_relatorio.date()
        )
        fim_q = (
            self.data_fim_relatorio.date()
        )

        if inicio_q > fim_q:
            QMessageBox.warning(
                self,
                "Período inválido",
                "A data inicial não pode ser posterior à data final."
            )
            return

        inicio = inicio_q.toString(
            "yyyy-MM-dd"
        )
        fim = fim_q.toString(
            "yyyy-MM-dd"
        )

        concurso = obter_concurso_ativo()

        self.rotulo_perfil_relatorio.setText(
            f"Perfil: {concurso[1]}"
        )

        self.rotulo_periodo_relatorio.setText(
            (
                f"{inicio_q.toString('dd/MM/yyyy')} "
                f"→ {fim_q.toString('dd/MM/yyyy')}"
            )
        )

        resumo = obter_relatorio_periodo(
            inicio,
            fim,
            concurso[0]
        )

        quantidade_dias = (
            inicio_q.daysTo(
                fim_q
            )
            + 1
        )

        fim_anterior_q = (
            inicio_q.addDays(
                -1
            )
        )

        inicio_anterior_q = (
            fim_anterior_q.addDays(
                -(
                    quantidade_dias
                    - 1
                )
            )
        )

        anterior = obter_relatorio_periodo(
            inicio_anterior_q.toString(
                "yyyy-MM-dd"
            ),
            fim_anterior_q.toString(
                "yyyy-MM-dd"
            ),
            concurso[0]
        )

        disciplinas = (
            obter_relatorio_disciplinas_periodo(
                inicio,
                fim,
                concurso[0]
            )
        )

        topicos = (
            obter_relatorio_topicos_periodo(
                inicio,
                fim,
                concurso[0]
            )
        )

        diario = (
            obter_relatorio_diario_periodo(
                inicio,
                fim,
                concurso[0]
            )
        )

        estrategico = (
            obter_relatorio_estrategico(
                inicio,
                fim,
                concurso[0]
            )
        )

        self.dados_relatorio_resumo = resumo
        self.dados_relatorio_comparacao = anterior
        self.dados_relatorio_estrategico = estrategico
        self.dados_relatorio_disciplinas = disciplinas
        self.dados_relatorio_topicos = topicos
        self.dados_relatorio_diario = diario

        self.atualizar_relatorio_estrategico(
            estrategico
        )

        # ----------------------------------------------------
        # RESUMO
        # ----------------------------------------------------

        self.rel_card_questoes.setText(
            str(
                resumo["questoes"]
            )
        )
        self.rel_card_acertos.setText(
            str(
                resumo["acertos"]
            )
        )
        self.rel_card_percentual.setText(
            formatar_percentual(
                resumo["percentual"]
            )
        )
        self.rel_card_revisoes.setText(
            str(
                resumo["revisoes"]
            )
        )
        self.rel_card_topicos.setText(
            str(
                resumo["topicos"]
            )
        )
        self.rel_card_disciplinas.setText(
            str(
                resumo["disciplinas"]
            )
        )

        # ----------------------------------------------------
        # COMPARAÇÃO
        # ----------------------------------------------------

        self.rotulo_periodo_anterior.setText(
            (
                f"{inicio_anterior_q.toString('dd/MM/yyyy')} "
                f"→ {fim_anterior_q.toString('dd/MM/yyyy')}"
            )
        )

        def calcular_tendencia_numero(
            atual,
            anterior_valor
        ):
            atual = float(
                atual or 0
            )
            anterior_valor = float(
                anterior_valor or 0
            )

            texto = self._comparar_numero(
                atual,
                anterior_valor
            )

            if anterior_valor == 0:
                if atual > 0:
                    return (
                        f"▲ {texto}",
                        "positive"
                    )
                return (
                    "• 0%",
                    "neutral"
                )

            diferenca = (
                atual
                - anterior_valor
            )

            if diferenca > 0:
                return (
                    f"▲ {texto}",
                    "positive"
                )
            if diferenca < 0:
                return (
                    f"▼ {texto}",
                    "negative"
                )

            return (
                "• 0,0%",
                "neutral"
            )

        texto_questoes, tendencia_questoes = (
            calcular_tendencia_numero(
                resumo["questoes"],
                anterior["questoes"]
            )
        )

        texto_revisoes, tendencia_revisoes = (
            calcular_tendencia_numero(
                resumo["revisoes"],
                anterior["revisoes"]
            )
        )

        if (
            resumo["percentual"] is None
            and anterior["percentual"] is None
        ):
            texto_desempenho = "• 0,0 p.p."
            tendencia_desempenho = "neutral"

        elif anterior["percentual"] is None:
            texto_desempenho = (
                "▲ novo"
                if resumo["percentual"] is not None
                else "• sem dados"
            )
            tendencia_desempenho = (
                "positive"
                if resumo["percentual"] is not None
                else "neutral"
            )

        elif resumo["percentual"] is None:
            texto_desempenho = "▼ sem dados"
            tendencia_desempenho = "negative"

        else:
            diferenca = (
                resumo["percentual"]
                - anterior["percentual"]
            )

            if diferenca > 0:
                texto_desempenho = (
                    f"▲ +{diferenca:.1f} p.p."
                    .replace(
                        ".",
                        ","
                    )
                )
                tendencia_desempenho = "positive"

            elif diferenca < 0:
                texto_desempenho = (
                    f"▼ {diferenca:.1f} p.p."
                    .replace(
                        ".",
                        ","
                    )
                )
                tendencia_desempenho = "negative"

            else:
                texto_desempenho = "• 0,0 p.p."
                tendencia_desempenho = "neutral"

        self.atualizar_indicador_comparacao(
            self.rel_comp_questoes,
            texto_questoes,
            tendencia_questoes
        )

        self.atualizar_indicador_comparacao(
            self.rel_comp_revisoes,
            texto_revisoes,
            tendencia_revisoes
        )

        self.atualizar_indicador_comparacao(
            self.rel_comp_desempenho,
            texto_desempenho,
            tendencia_desempenho
        )

        # Compatibilidade interna.
        self.comparacao_relatorio.setText(
            (
                f"Questões {texto_questoes} | "
                f"Revisões {texto_revisoes} | "
                f"Desempenho {texto_desempenho}"
            )
        )

        # ----------------------------------------------------
        # CONTADORES DAS ABAS
        # ----------------------------------------------------

        qtd_disciplinas = len(
            disciplinas
        )
        qtd_topicos = len(
            topicos
        )
        qtd_dias = len(
            diario
        )

        self.rel_contagem_disciplinas.setText(
            (
                "1 disciplina"
                if qtd_disciplinas == 1
                else f"{qtd_disciplinas} disciplinas"
            )
        )

        self.rel_contagem_topicos.setText(
            (
                "1 tópico"
                if qtd_topicos == 1
                else f"{qtd_topicos} tópicos"
            )
        )

        self.rel_contagem_dias.setText(
            (
                "1 dia"
                if qtd_dias == 1
                else f"{qtd_dias} dias"
            )
        )

        # ----------------------------------------------------
        # TABELA DISCIPLINAS
        # ----------------------------------------------------

        self.tabela_relatorio_disciplinas.setRowCount(
            qtd_disciplinas
        )

        for linha, dado in enumerate(
            disciplinas
        ):
            valores = [
                dado[0],
                str(
                    dado[1]
                ),
                str(
                    dado[2]
                ),
                str(
                    dado[3]
                ),
                formatar_percentual(
                    dado[4]
                ),
                str(
                    dado[5]
                )
            ]

            for coluna, valor in enumerate(
                valores
            ):
                item = QTableWidgetItem(
                    valor
                )

                if coluna in (
                    1,
                    2,
                    3,
                    4,
                    5
                ):
                    item.setTextAlignment(
                        Qt.AlignCenter
                    )

                if (
                    coluna == 4
                    and dado[4] is not None
                ):
                    if dado[4] < 60:
                        aplicar_destaque_tabela(
                            item,
                            "perigo",
                            True
                        )
                    elif dado[4] < 70:
                        aplicar_destaque_tabela(
                            item,
                            "alerta",
                            True
                        )
                    elif dado[4] < 80:
                        aplicar_destaque_tabela(
                            item,
                            "atencao",
                            True
                        )
                    elif dado[4] >= 90:
                        aplicar_destaque_tabela(
                            item,
                            "sucesso",
                            False
                        )

                self.tabela_relatorio_disciplinas.setItem(
                    linha,
                    coluna,
                    item
                )

            self.tabela_relatorio_disciplinas.setRowHeight(
                linha,
                31
            )

        # ----------------------------------------------------
        # TABELA TÓPICOS
        # ----------------------------------------------------

        self.tabela_relatorio_topicos.setRowCount(
            qtd_topicos
        )

        for linha, dado in enumerate(
            topicos
        ):
            valores = [
                dado[1],
                dado[2],
                str(
                    dado[3]
                ),
                str(
                    dado[4]
                ),
                str(
                    dado[5]
                ),
                formatar_percentual(
                    dado[6]
                ),
                formatar_data(
                    dado[7]
                ),
                formatar_data(
                    dado[8]
                )
            ]

            for coluna, valor in enumerate(
                valores
            ):
                item = QTableWidgetItem(
                    valor
                )

                if coluna == 1:
                    item.setData(
                        Qt.UserRole,
                        dado[0]
                    )

                if coluna in (
                    2,
                    3,
                    4,
                    5,
                    6,
                    7
                ):
                    item.setTextAlignment(
                        Qt.AlignCenter
                    )

                if (
                    coluna == 5
                    and dado[6] is not None
                ):
                    if dado[6] < 60:
                        aplicar_destaque_tabela(
                            item,
                            "perigo",
                            True
                        )
                    elif dado[6] < 70:
                        aplicar_destaque_tabela(
                            item,
                            "alerta",
                            True
                        )
                    elif dado[6] < 80:
                        aplicar_destaque_tabela(
                            item,
                            "atencao",
                            True
                        )
                    elif dado[6] >= 90:
                        aplicar_destaque_tabela(
                            item,
                            "sucesso",
                            False
                        )

                self.tabela_relatorio_topicos.setItem(
                    linha,
                    coluna,
                    item
                )

            self.tabela_relatorio_topicos.setRowHeight(
                linha,
                31
            )

        # ----------------------------------------------------
        # TABELA DIÁRIA
        # ----------------------------------------------------

        self.tabela_relatorio_diario.setRowCount(
            qtd_dias
        )

        for linha, dado in enumerate(
            diario
        ):
            valores = [
                formatar_data(
                    dado[0]
                ),
                str(
                    dado[1]
                ),
                str(
                    dado[2]
                ),
                str(
                    dado[3]
                ),
                formatar_percentual(
                    dado[4]
                )
            ]

            for coluna, valor in enumerate(
                valores
            ):
                item = QTableWidgetItem(
                    valor
                )

                item.setTextAlignment(
                    Qt.AlignCenter
                )

                if (
                    coluna == 4
                    and dado[4] is not None
                ):
                    if dado[4] < 60:
                        aplicar_destaque_tabela(
                            item,
                            "perigo",
                            False
                        )
                    elif dado[4] >= 90:
                        aplicar_destaque_tabela(
                            item,
                            "sucesso",
                            False
                        )

                self.tabela_relatorio_diario.setItem(
                    linha,
                    coluna,
                    item
                )

            self.tabela_relatorio_diario.setRowHeight(
                linha,
                31
            )


    def atualizar_relatorio_estrategico(
        self,
        dados
    ):
        dados = dados or {}
        situacao = dados.get(
            "situacao",
            {}
        )
        evolucao = dados.get(
            "evolucao",
            {}
        )
        periodo = dados.get(
            "periodo",
            {}
        )

        def percentual(valor):
            if valor is None:
                return "—"
            return (
                f"{float(valor):.1f}%"
                .replace(".", ",")
            )

        def pontos(valor):
            if valor is None:
                return "—"
            valor = float(valor)
            if abs(valor) < 0.05:
                return "Estável"
            seta = "▲" if valor > 0 else "▼"
            sinal = "+" if valor > 0 else ""
            return (
                f"{seta} {sinal}{valor:.1f} p.p."
                .replace(".", ",")
            )

        preparacao = situacao.get(
            "preparacao",
            "Evidência insuficiente"
        )
        self.rel_estrategico_preparacao.setText(
            preparacao
        )
        estado_preparacao = {
            "Atenção": "attention",
            "Em construção": "building",
            "Boa": "good",
            "Forte": "strong",
            "Evidência insuficiente": "insufficient",
        }.get(preparacao, "insufficient")
        self.rel_estrategico_preparacao.setProperty(
            "prepState",
            estado_preparacao
        )
        self.rel_estrategico_preparacao.style().unpolish(
            self.rel_estrategico_preparacao
        )
        self.rel_estrategico_preparacao.style().polish(
            self.rel_estrategico_preparacao
        )

        criticas = int(
            situacao.get("criticas_abertas") or 0
        )
        recorrentes = int(
            situacao.get("recorrentes_abertas") or 0
        )
        self.rel_estrategico_preparacao_detalhe.setText(
            (
                f"{criticas} críticas • {recorrentes} recorrentes abertas"
                if (criticas or recorrentes)
                else "classificação baseada em evidências atuais"
            )
        )

        dominio = situacao.get(
            "dominio_medio"
        )
        self.rel_estrategico_dominio.setText(
            "—"
            if dominio is None
            else f"{float(dominio):.0f} / 100"
        )
        self.rel_estrategico_dominio_detalhe.setText(
            (
                f"{situacao.get('topicos_com_evidencia', 0)} tópicos com evidência"
            )
        )

        desempenho = situacao.get(
            "desempenho"
        )
        self.rel_estrategico_desempenho.setText(
            percentual(desempenho)
        )
        self.rel_estrategico_desempenho_detalhe.setText(
            (
                f"{int(situacao.get('questoes') or 0)} questões • "
                f"{int(situacao.get('dias_ativos') or 0)} dias ativos"
            )
        )

        cobertura = float(
            situacao.get("cobertura_evidencia") or 0.0
        )
        self.rel_estrategico_cobertura.setText(
            percentual(cobertura)
        )
        self.rel_estrategico_cobertura_detalhe.setText(
            (
                f"{int(situacao.get('topicos_com_evidencia') or 0)} de "
                f"{int(situacao.get('total_topicos') or 0)} tópicos"
            )
        )

        try:
            inicio_anterior = datetime.strptime(
                periodo.get("inicio_anterior", ""),
                "%Y-%m-%d"
            ).strftime("%d/%m/%Y")
            fim_anterior = datetime.strptime(
                periodo.get("fim_anterior", ""),
                "%Y-%m-%d"
            ).strftime("%d/%m/%Y")
            texto_periodo = (
                f"Comparado com {inicio_anterior} → {fim_anterior}"
            )
        except (TypeError, ValueError):
            texto_periodo = "Período anterior equivalente"

        self.rel_estrategico_periodo_anterior.setText(
            texto_periodo
        )

        self.rel_estrategico_delta_desempenho.setText(
            pontos(
                evolucao.get("desempenho_delta")
            )
        )
        self.rel_estrategico_delta_desempenho.setProperty(
            "trend",
            (
                "positive"
                if (evolucao.get("desempenho_delta") or 0) > 0.05
                else "negative"
                if (evolucao.get("desempenho_delta") or 0) < -0.05
                else "neutral"
            )
        )
        self.rel_estrategico_delta_desempenho.style().unpolish(
            self.rel_estrategico_delta_desempenho
        )
        self.rel_estrategico_delta_desempenho.style().polish(
            self.rel_estrategico_delta_desempenho
        )

        delta_volume = int(
            evolucao.get("questoes_delta") or 0
        )
        anterior_resumo = evolucao.get(
            "resumo_anterior",
            {}
        )
        if delta_volume > 0:
            texto_volume = f"▲ +{delta_volume}"
        elif delta_volume < 0:
            texto_volume = f"▼ {delta_volume}"
        else:
            texto_volume = "Estável"
        texto_volume += (
            f" • anterior {int(anterior_resumo.get('questoes') or 0)}"
        )
        self.rel_estrategico_delta_volume.setText(
            texto_volume
        )

        maior = evolucao.get(
            "maior_evolucao"
        )
        queda = evolucao.get(
            "maior_queda"
        )

        self.rel_estrategico_maior_evolucao.setText(
            (
                "Sem base comparável"
                if not maior
                else (
                    f"{maior.get('disciplina', '—')} • "
                    f"{pontos(maior.get('variacao'))}"
                )
            )
        )
        self.rel_estrategico_maior_queda.setText(
            (
                "Sem base comparável"
                if not queda
                else (
                    f"{queda.get('disciplina', '—')} • "
                    f"{pontos(queda.get('variacao'))}"
                )
            )
        )

        riscos = list(
            dados.get("riscos") or []
        )
        for indice, label in enumerate(
            self.rel_estrategico_riscos
        ):
            if indice >= len(riscos):
                label.setVisible(False)
                continue
            item = riscos[indice]
            label.setVisible(True)
            nivel = item.get("nivel", "medio")
            label.setProperty(
                "riskLevel",
                nivel
            )
            label.setText(
                (
                    f"<b>{item.get('titulo', 'Atenção')}</b><br>"
                    f"{item.get('detalhe', '')}"
                )
            )
            label.style().unpolish(label)
            label.style().polish(label)

        acoes = list(
            dados.get("acoes") or []
        )
        for indice, label in enumerate(
            self.rel_estrategico_acoes
        ):
            if indice >= len(acoes):
                label.setVisible(False)
                continue
            item = acoes[indice]
            label.setVisible(True)
            label.setText(
                (
                    f"<b>{indice + 1}. {item.get('titulo', 'Próxima ação')}</b><br>"
                    f"{item.get('detalhe', '')}<br>"
                    f"<i>→ {item.get('acao', '')}</i>"
                )
            )

        disciplinas = list(
            dados.get("disciplinas") or []
        )
        self.rel_estrategico_contagem_disciplinas.setText(
            (
                f"{len(disciplinas)} disciplina"
                if len(disciplinas) == 1
                else f"{len(disciplinas)} disciplinas"
            )
        )

        tabela = self.tabela_relatorio_estrategico_disciplinas
        tabela.setRowCount(
            len(disciplinas)
        )

        for linha, item in enumerate(disciplinas):
            dominio_item = item.get("dominio")
            desempenho_item = item.get("desempenho")
            cobertura_item = item.get("cobertura_evidencia")
            variacao_item = item.get("variacao")

            valores = [
                item.get("disciplina") or "—",
                item.get("preparacao") or "—",
                (
                    "—"
                    if dominio_item is None
                    else f"{float(dominio_item):.0f}/100"
                ),
                percentual(desempenho_item),
                percentual(cobertura_item),
                pontos(variacao_item),
            ]

            for coluna, valor in enumerate(valores):
                celula = QTableWidgetItem(str(valor))
                if coluna == 0:
                    celula.setTextAlignment(
                        Qt.AlignLeft | Qt.AlignVCenter
                    )
                else:
                    celula.setTextAlignment(
                        Qt.AlignCenter
                    )

                if coluna == 1:
                    estado = item.get("preparacao")
                    if estado == "Atenção":
                        aplicar_destaque_tabela(
                            celula,
                            "perigo",
                            True
                        )
                    elif estado == "Em construção":
                        aplicar_destaque_tabela(
                            celula,
                            "alerta",
                            True
                        )
                    elif estado == "Forte":
                        aplicar_destaque_tabela(
                            celula,
                            "sucesso",
                            True
                        )

                tabela.setItem(
                    linha,
                    coluna,
                    celula
                )

            tabela.setRowHeight(
                linha,
                31
            )


    def abrir_topico_relatorio(
        self,
        linha,
        coluna
    ):
        item = self.tabela_relatorio_topicos.item(
            linha,
            1
        )

        if item is None:
            return

        topico_id = item.data(
            Qt.UserRole
        )

        janela = JanelaTopico(
            topico_id,
            item.text(),
            self
        )

        janela.exec()

        self.atualizar_relatorios()

    def exportar_relatorio_csv(self):
        if self.dados_relatorio_resumo is None:
            self.atualizar_relatorios()

        concurso = obter_concurso_ativo()

        inicio_q = (
            self.data_inicio_relatorio.date()
        )
        fim_q = (
            self.data_fim_relatorio.date()
        )

        nome_padrao = (
            "relatorio_estudos_"
            f"{inicio_q.toString('yyyy-MM-dd')}_"
            f"{fim_q.toString('yyyy-MM-dd')}.csv"
        )

        caminho, _ = QFileDialog.getSaveFileName(
            self,
            "Exportar relatório CSV",
            str(
                Path.home()
                / nome_padrao
            ),
            "Arquivo CSV (*.csv)"
        )

        if not caminho:
            return

        if not caminho.lower().endswith(
            ".csv"
        ):
            caminho += ".csv"

        try:
            with open(
                caminho,
                "w",
                newline="",
                encoding="utf-8-sig"
            ) as arquivo:
                escritor = csv.writer(
                    arquivo,
                    delimiter=";"
                )

                resumo = (
                    self.dados_relatorio_resumo
                )

                escritor.writerow([
                    "RELATÓRIO DE ESTUDOS"
                ])
                escritor.writerow([
                    "Perfil",
                    concurso[1]
                ])
                escritor.writerow([
                    "Início",
                    inicio_q.toString(
                        "dd/MM/yyyy"
                    )
                ])
                escritor.writerow([
                    "Fim",
                    fim_q.toString(
                        "dd/MM/yyyy"
                    )
                ])
                escritor.writerow([])
                escritor.writerow([
                    "Revisões",
                    resumo["revisoes"]
                ])
                escritor.writerow([
                    "Questões",
                    resumo["questoes"]
                ])
                escritor.writerow([
                    "Acertos",
                    resumo["acertos"]
                ])
                escritor.writerow([
                    "Desempenho",
                    (
                        ""
                        if resumo[
                            "percentual"
                        ] is None
                        else str(
                            resumo[
                                "percentual"
                            ]
                        ).replace(
                            ".",
                            ","
                        )
                        + "%"
                    )
                ])
                escritor.writerow([
                    "Tópicos estudados",
                    resumo["topicos"]
                ])
                escritor.writerow([
                    "Disciplinas estudadas",
                    resumo["disciplinas"]
                ])

                estrategico = (
                    self.dados_relatorio_estrategico
                    or {}
                )
                situacao_estrategica = estrategico.get(
                    "situacao",
                    {}
                )

                escritor.writerow([])
                escritor.writerow([
                    "RELATÓRIO ESTRATÉGICO"
                ])
                escritor.writerow([
                    "Estado de preparação",
                    situacao_estrategica.get(
                        "preparacao",
                        "—"
                    )
                ])
                escritor.writerow([
                    "Domínio médio",
                    (
                        ""
                        if situacao_estrategica.get("dominio_medio") is None
                        else str(
                            round(
                                float(situacao_estrategica.get("dominio_medio")),
                                1
                            )
                        ).replace(".", ",")
                        + "/100"
                    )
                ])
                escritor.writerow([
                    "Desempenho interno no período",
                    (
                        ""
                        if situacao_estrategica.get("desempenho") is None
                        else str(
                            round(
                                float(situacao_estrategica.get("desempenho")),
                                1
                            )
                        ).replace(".", ",")
                        + "%"
                    )
                ])
                escritor.writerow([
                    "Cobertura com evidência",
                    str(
                        round(
                            float(
                                situacao_estrategica.get(
                                    "cobertura_evidencia"
                                )
                                or 0.0
                            ),
                            1
                        )
                    ).replace(".", ",")
                    + "%"
                ])

                escritor.writerow([])
                escritor.writerow([
                    "RISCOS"
                ])
                escritor.writerow([
                    "Nível",
                    "Risco",
                    "Detalhe"
                ])
                for item in estrategico.get("riscos") or []:
                    escritor.writerow([
                        item.get("nivel", ""),
                        item.get("titulo", ""),
                        item.get("detalhe", ""),
                    ])

                escritor.writerow([])
                escritor.writerow([
                    "PRÓXIMAS AÇÕES"
                ])
                escritor.writerow([
                    "Prioridade",
                    "Recomendação",
                    "Motivo",
                    "Ação"
                ])
                for ordem, item in enumerate(
                    estrategico.get("acoes") or [],
                    1
                ):
                    escritor.writerow([
                        ordem,
                        item.get("titulo", ""),
                        item.get("detalhe", ""),
                        item.get("acao", ""),
                    ])

                escritor.writerow([])
                escritor.writerow([
                    "PREPARAÇÃO POR DISCIPLINA"
                ])
                escritor.writerow([
                    "Disciplina",
                    "Preparação",
                    "Domínio",
                    "Desempenho",
                    "Cobertura com evidência",
                    "Variação"
                ])
                for item in estrategico.get("disciplinas") or []:
                    escritor.writerow([
                        item.get("disciplina", ""),
                        item.get("preparacao", ""),
                        (
                            ""
                            if item.get("dominio") is None
                            else str(round(float(item.get("dominio")), 1)).replace(".", ",")
                            + "/100"
                        ),
                        (
                            ""
                            if item.get("desempenho") is None
                            else str(round(float(item.get("desempenho")), 1)).replace(".", ",")
                            + "%"
                        ),
                        str(round(float(item.get("cobertura_evidencia") or 0.0), 1)).replace(".", ",") + "%",
                        (
                            ""
                            if item.get("variacao") is None
                            else str(round(float(item.get("variacao")), 1)).replace(".", ",")
                            + " p.p."
                        ),
                    ])

                escritor.writerow([])
                escritor.writerow([
                    "POR DISCIPLINA"
                ])
                escritor.writerow([
                    "Disciplina",
                    "Revisões",
                    "Questões",
                    "Acertos",
                    "Desempenho",
                    "Tópicos"
                ])

                for dado in self.dados_relatorio_disciplinas:
                    escritor.writerow([
                        dado[0],
                        dado[1],
                        dado[2],
                        dado[3],
                        (
                            ""
                            if dado[4] is None
                            else str(
                                dado[4]
                            ).replace(
                                ".",
                                ","
                            )
                            + "%"
                        ),
                        dado[5]
                    ])

                escritor.writerow([])
                escritor.writerow([
                    "POR TÓPICO"
                ])
                escritor.writerow([
                    "Disciplina",
                    "Tópico",
                    "Revisões",
                    "Questões",
                    "Acertos",
                    "Desempenho",
                    "Primeira no período",
                    "Última no período"
                ])

                for dado in self.dados_relatorio_topicos:
                    escritor.writerow([
                        dado[1],
                        dado[2],
                        dado[3],
                        dado[4],
                        dado[5],
                        (
                            ""
                            if dado[6] is None
                            else str(
                                dado[6]
                            ).replace(
                                ".",
                                ","
                            )
                            + "%"
                        ),
                        formatar_data(
                            dado[7]
                        ),
                        formatar_data(
                            dado[8]
                        )
                    ])

                escritor.writerow([])
                escritor.writerow([
                    "POR DIA"
                ])
                escritor.writerow([
                    "Data",
                    "Revisões",
                    "Questões",
                    "Acertos",
                    "Desempenho"
                ])

                for dado in self.dados_relatorio_diario:
                    escritor.writerow([
                        formatar_data(
                            dado[0]
                        ),
                        dado[1],
                        dado[2],
                        dado[3],
                        (
                            ""
                            if dado[4] is None
                            else str(
                                dado[4]
                            ).replace(
                                ".",
                                ","
                            )
                            + "%"
                        )
                    ])

            QMessageBox.information(
                self,
                "Relatório exportado",
                (
                    "Arquivo CSV criado com sucesso:\n\n"
                    f"{caminho}"
                )
            )

        except Exception as erro:
            QMessageBox.critical(
                self,
                "Falha ao exportar",
                (
                    "Não foi possível criar o CSV.\n\n"
                    f"{erro}"
                )
            )

    def criar_aba_laboratorio_algoritmo(self):
        aba = QWidget()
        aba_raiz = QVBoxLayout(aba)
        aba_raiz.setContentsMargins(0, 0, 0, 0)
        aba_raiz.setSpacing(0)

        # O Laboratório possui vários blocos verticais. Em resoluções menores
        # ele não deve cortar a parte inferior: toda a aba passa a ser rolável.
        scroll = QScrollArea()
        scroll.setObjectName("algorithmLabScroll")
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QFrame.NoFrame)
        scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)

        conteudo = QWidget()
        conteudo.setObjectName("algorithmLabContent")
        raiz = QVBoxLayout(conteudo)
        raiz.setContentsMargins(12, 12, 12, 12)
        raiz.setSpacing(10)

        topo = QFrame()
        topo.setObjectName("myEvolutionPanel")
        tl = QVBoxLayout(topo)
        tl.setContentsMargins(14, 12, 14, 12)
        tl.setSpacing(8)
        titulo = QLabel("Laboratório do Algoritmo")
        titulo.setObjectName("myEvolutionSectionTitle")
        desc = QLabel("Simule o Motor V5 sem alterar o comportamento real. Aplicar configuração é uma ação separada.")
        desc.setObjectName("mutedLabel")
        desc.setWordWrap(True)
        tl.addWidget(titulo)
        tl.addWidget(desc)

        pesos_linha = QHBoxLayout()
        pesos_linha.setSpacing(8)
        self.lab_peso_urgencia = QSpinBox(); self.lab_peso_urgencia.setRange(0, 100)
        self.lab_peso_necessidade = QSpinBox(); self.lab_peso_necessidade.setRange(0, 100)
        self.lab_peso_momento = QSpinBox(); self.lab_peso_momento.setRange(0, 100)
        config = carregar_configuracao_motor_v5()
        self.lab_peso_urgencia.setValue(round(config["pesos"]["urgencia"]))
        self.lab_peso_necessidade.setValue(round(config["pesos"]["necessidade"]))
        self.lab_peso_momento.setValue(round(config["pesos"]["momento"]))
        for texto, widget in (("Urgência", self.lab_peso_urgencia), ("Necessidade", self.lab_peso_necessidade), ("Momento", self.lab_peso_momento)):
            bloco = QVBoxLayout(); rot = QLabel(texto); rot.setObjectName("myEvolutionStatLabel")
            widget.setSuffix("%")
            bloco.addWidget(rot); bloco.addWidget(widget); pesos_linha.addLayout(bloco)
        self.lab_proteger = QCheckBox("Proteger revisões vencidas e previstas para hoje")
        self.lab_proteger.setChecked(bool(config["proteger_revisoes_vencidas"]))
        pesos_linha.addWidget(self.lab_proteger, 1, Qt.AlignBottom)
        tl.addLayout(pesos_linha)

        acoes = QHBoxLayout()
        self.lab_pesos_info = QLabel("")
        self.lab_pesos_info.setObjectName("mutedLabel")
        acoes.addWidget(self.lab_pesos_info, 1)
        simular = QPushButton("Simular resultado"); simular.setObjectName("toolbarButton"); simular.clicked.connect(self.atualizar_laboratorio_algoritmo)
        aplicar = QPushButton("Aplicar configuração"); aplicar.setObjectName("studyManualButton"); aplicar.clicked.connect(self.aplicar_configuracao_laboratorio)
        padrao = QPushButton("Restaurar padrão"); padrao.setObjectName("subtleButton"); padrao.clicked.connect(self.restaurar_padrao_laboratorio)
        acoes.addWidget(simular); acoes.addWidget(aplicar); acoes.addWidget(padrao)
        tl.addLayout(acoes)
        raiz.addWidget(topo)

