    def pesos_laboratorio_algoritmo(self):
        return {"urgencia": self.lab_peso_urgencia.value(), "necessidade": self.lab_peso_necessidade.value(), "momento": self.lab_peso_momento.value()}

    def atualizar_rotulo_pesos_laboratorio(self, *args):
        if not hasattr(self,"lab_pesos_info"): return
        total=sum(self.pesos_laboratorio_algoritmo().values())
        self.lab_pesos_info.setText(f"Pesos informados: {total}% • a simulação normaliza automaticamente para 100%")

    def atualizar_laboratorio_algoritmo(self, *args):
        if not hasattr(self,"lab_tabela"): return
        try:
            d=self._dados_motor_v5(self.pesos_laboratorio_algoritmo(), self.lab_proteger.isChecked())
            rel=montar_laboratorio(fila=d["fila"],adaptativas=d["adaptativas"],contexto=d["contexto"],calibracao=d["calibracao"],perfil_decisoes=d["perfil_decisoes"],hoje=QDate.currentDate().toString("yyyy-MM-dd"),pesos=d["pesos"],proteger_revisoes_vencidas=d["proteger"],usar_calibracao=d["usar_calibracao"],usar_historico_decisoes=d["usar_decisoes"])
        except Exception as erro:
            self.lab_escolhido.setText("Falha na simulação"); self.lab_criterio.setText(str(erro)); return
        self.lab_relatorio=rel
        rec=rel.get("recomendacao") or {}; e=rec.get("eixos_v5") or {}
        self.lab_score.setText(f"{float(rec.get('score_total') or 0):.1f}"); self.lab_urgencia.setText(f"{float(e.get('urgencia') or 0):.0f}/100"); self.lab_necessidade.setText(f"{float(e.get('necessidade') or 0):.0f}/100"); self.lab_momento.setText(f"{float(e.get('momento') or 0):.0f}/100")
        self.lab_escolhido.setText(f"{rec.get('disciplina') or 'Estudo livre'} › {rec.get('topico') or 'Sem tópico específico'}")
        self.lab_criterio.setText(str(rec.get("criterio_selecao_v5") or "—")); self.lab_comparacao.setText(str(rel.get("comparacao") or "—"))
        ranking=list(rel.get("ranking") or []); self.lab_tabela.setRowCount(len(ranking))
        for r,item in enumerate(ranking):
            vals=[str(r+1),str(item.get("disciplina") or "—"),str(item.get("topico") or "—"),f"{float(item.get('urgencia') or 0):.0f}",f"{float(item.get('necessidade') or 0):.0f}",f"{float(item.get('momento') or 0):.0f}",f"{float(item.get('score_total') or 0):.1f}","Protegida" if item.get("faixa_temporal_protegida") else "Flexível"]
            for c,v in enumerate(vals): self.lab_tabela.setItem(r,c,QTableWidgetItem(v))
            self.lab_tabela.setRowHeight(r,30)

    def aplicar_configuracao_laboratorio(self):
        salvar_configuracao_motor_v5(self.pesos_laboratorio_algoritmo(), self.lab_proteger.isChecked())
        self.cache_analitico.invalidar(); self.atualizar_dashboard(); self.atualizar_laboratorio_algoritmo()
        QMessageBox.information(self,"Motor V5","Configuração aplicada. As próximas recomendações usarão estes pesos.")

    def restaurar_padrao_laboratorio(self):
        config=restaurar_padrao_motor_v5(); self.lab_peso_urgencia.setValue(round(config["pesos"]["urgencia"])); self.lab_peso_necessidade.setValue(round(config["pesos"]["necessidade"])); self.lab_peso_momento.setValue(round(config["pesos"]["momento"])); self.lab_proteger.setChecked(True)
        self.cache_analitico.invalidar(); self.atualizar_dashboard(); self.atualizar_laboratorio_algoritmo()

    def explicar_busca_laboratorio(self):
        if not self.lab_relatorio: self.atualizar_laboratorio_algoritmo()
        self.lab_explicacao.setText(explicar_topico_laboratorio(self.lab_relatorio or {}, self.lab_busca.text()))

    def selecionar_linha_laboratorio(self):
        linha=self.lab_tabela.currentRow()
        ranking=list((self.lab_relatorio or {}).get("ranking") or [])
        if 0 <= linha < len(ranking):
            item=ranking[linha]; self.lab_explicacao.setText(explicar_topico_laboratorio(self.lab_relatorio, str(item.get("topico") or item.get("disciplina") or "")))

