        def criar_indicador_evolucao(
            titulo_texto
        ):
            card = QFrame()
            card.setObjectName(
                "evolutionStat"
            )

            card_layout = QVBoxLayout(
                card
            )
            card_layout.setContentsMargins(
                12,
                8,
                12,
                8
            )
            card_layout.setSpacing(
                2
            )

            rotulo = QLabel(
                titulo_texto
            )
            rotulo.setObjectName(
                "miniStatLabel"
            )

            valor = QLabel(
                "—"
            )
            valor.setObjectName(
                "miniStatValue"
            )

            tendencia = QLabel(
                "—"
            )
            tendencia.setObjectName(
                "evolutionTrend"
            )

            card_layout.addWidget(
                rotulo
            )
            card_layout.addWidget(
                valor
            )
            card_layout.addWidget(
                tendencia
            )

            return (
                card,
                valor,
                tendencia
            )

        (
            card,
            self.evolucao_desempenho,
            self.evolucao_desempenho_tendencia
        ) = criar_indicador_evolucao(
            "Desempenho"
        )
        indicadores_evolucao.addWidget(
            card,
            0,
            0
        )

