    def filtrar_alertas_conteudo(self):
        if not hasattr(
            self,
            "dados_alertas_conteudo"
        ):
            return

        busca = self.normalizar_texto_progresso(
            self.alertas_busca.text()
        )

        nivel = (
            self.alertas_filtro_nivel.currentText()
        )
        tipo = (
            self.alertas_filtro_tipo.currentText()
        )

        filtrados = []

        for item in self.dados_alertas_conteudo:
            if (
                nivel != "Todos os níveis"
                and item[
                    "nivel_alerta"
                ] != nivel
            ):
                continue

            if (
                tipo != "Todos os tipos"
                and tipo not in item[
                    "tipos_alerta"
                ]
            ):
                continue

            if busca:
                alvo = self.normalizar_texto_progresso(
                    (
                        f"{item['disciplina']} "
                        f"{item['topico']} "
                        f"{item['nivel_alerta']} "
                        f"{item['motivo_alerta']}"
                    )
                )

                termos = [
                    termo
                    for termo in busca.split(
                        " "
                    )
                    if termo
                ]

                if not all(
                    termo in alvo
                    for termo in termos
                ):
                    continue

            filtrados.append(
                item
            )

        self.alertas_vazio.setVisible(
            len(
                filtrados
            ) == 0
        )
        self.tabela_alertas_conteudo.setVisible(
            len(
                filtrados
            ) > 0
        )

        self.tabela_alertas_conteudo.setRowCount(
            len(
                filtrados
            )
        )

        mapa_nivel = {
            "Crítico": "perigo",
            "Atenção": "alerta",
            "Monitorar": "atencao",
        }

        for linha, item in enumerate(
            filtrados
        ):
            atraso_texto = (
                (
                    f"{item['dias_atraso']} d"
                )
                if item[
                    "dias_atraso"
                ] > 0
                else "—"
            )

            valores = [
                item[
                    "nivel_alerta"
                ],
                item[
                    "disciplina"
                ],
                item[
                    "topico"
                ],
                item[
                    "motivo_alerta"
                ],
                formatar_data(
                    item[
                        "ultima"
                    ]
                ),
                formatar_data(
                    item[
                        "proxima"
                    ]
                ),
                atraso_texto,
                formatar_percentual(
                    item[
                        "percentual"
                    ]
                ),
                "",
            ]

            for coluna, valor in enumerate(
                valores
            ):
                if coluna == 8:
                    continue

                celula = QTableWidgetItem(
                    valor
                )

                if coluna == 2:
                    celula.setData(
                        Qt.UserRole,
                        item[
                            "topico_id"
                        ]
                    )

                if coluna in (
                    0,
                    4,
                    5,
                    6,
                    7
                ):
                    celula.setTextAlignment(
                        Qt.AlignCenter
                    )

                if coluna == 0:
                    aplicar_destaque_tabela(
                        celula,
                        mapa_nivel.get(
                            item[
                                "nivel_alerta"
                            ],
                            "atencao"
                        ),
                        True
                    )

                if (
                    coluna == 7
                    and item[
                        "percentual"
                    ] is not None
                    and item[
                        "percentual"
                    ] < 70
                ):
                    aplicar_destaque_tabela(
                        celula,
                        "perigo",
                        False
                    )

                self.tabela_alertas_conteudo.setItem(
                    linha,
                    coluna,
                    celula
                )

            estrelas = IndicadorEstrelasFila(
                item[
                    "importancia"
                ]
            )
            self.tabela_alertas_conteudo.setCellWidget(
                linha,
                8,
                estrelas
            )

            self.tabela_alertas_conteudo.setRowHeight(
                linha,
                34
            )

    def abrir_topico_alerta(
        self,
        linha,
        coluna
    ):
        item = self.tabela_alertas_conteudo.item(
            linha,
            2
        )

        if item is None:
            return

        topico_id = item.data(
            Qt.UserRole
        )

        if topico_id is None:
            return

        janela = JanelaTopico(
            topico_id,
            item.text(),
            self
        )

        janela.exec()

        self.atualizar_dashboard()
        self.atualizar_estatisticas()

