    def atualizar_progresso_dashboard(
        self,
        concurso_id,
        metricas_globais=None
    ):
        if not hasattr(
            self,
            "dashboard_progresso_trabalhado"
        ):
            return

        dados = self.montar_dados_progresso_edital(
            concurso_id
        )

        total = len(
            dados
        )

        nao_iniciados = sum(
            1
            for item in dados
            if item["estado"] == "Não iniciado"
        )
        consolidando = sum(
            1
            for item in dados
            if item["estado"] == "Consolidando"
        )
        consolidados = sum(
            1
            for item in dados
            if item["estado"] == "Consolidado"
        )

        trabalhados = (
            total
            - nao_iniciados
        )

        cobertura_nucleo = (
            (metricas_globais or {})
            .get("topic_coverage_rate", {})
            .get("value")
        )
        cobertura = round(float(cobertura_nucleo)) if cobertura_nucleo is not None else 0

        self.dashboard_progresso_trabalhado.setText(
            f"{cobertura}%"
        )
        self.dashboard_progresso_barra.setValue(
            int(
                cobertura
            )
        )
        self.dashboard_progresso_contagem.setText(
            f"{trabalhados} de {total} tópicos"
        )
        self.dashboard_progresso_consolidando.setText(
            str(
                consolidando
            )
        )
        self.dashboard_progresso_consolidado.setText(
            str(
                consolidados
            )
        )
        self.dashboard_progresso_nao_iniciado.setText(
            str(
                nao_iniciados
            )
        )

        dominio_global = (
            (metricas_globais or {})
            .get("mastery_score", {})
            .get("value")
        )

        if dominio_global is not None:
            self.dashboard_dominio_medio.setText(
                f"{float(dominio_global):.0f}/100"
            )
        else:
            self.dashboard_dominio_medio.setText(
                "—"
            )

        self.atualizar_alertas_dashboard(
            concurso_id
        )

